-- 0. Country row (adds any territory missing from the base schema seed)
insert into public.countries (code, name) values
  ('YT', 'Mayotte')
on conflict (code) do update set name = excluded.name;

-- 1. Country root (level 1)
insert into public.locations (country_code, parent_id, name, location_type, level, path, sort_order)
select 'YT', null, 'Mayotte', 'Country', 1, 'mayotte', 0
on conflict (country_code, path) do update set
  name = excluded.name, location_type = excluded.location_type, level = excluded.level;

-- 2. Level 2 (3 rows)
insert into public.locations (country_code, parent_id, name, location_type, level, path, sort_order)
select 'YT', p.id, v.name, v.location_type, v.level, v.path, v.sort_order
from (values
    ('mayotte', 'Grande-Terre Island', 'Island / Administrative Area', 2, 'mayotte/grande-terre-island', 0),
    ('mayotte', 'Petite-Terre Island', 'Island / Administrative Area', 2, 'mayotte/petite-terre-island', 1),
    ('mayotte', 'Mayotte Islets and Lagoon', 'Lagoon / Islets Area', 2, 'mayotte/mayotte-islets-and-lagoon', 2)
) as v(parent_path, name, location_type, level, path, sort_order)
join public.locations p
  on p.country_code = 'YT' and p.path = v.parent_path
on conflict (country_code, path) do update set
  name = excluded.name, location_type = excluded.location_type, level = excluded.level,
  sort_order = excluded.sort_order, parent_id = excluded.parent_id;

